<script setup>
import {ref,onBeforeUnmount,computed,watch,shallowRef,defineAsyncComponent} from 'vue';
import {nativeViewerZip,NATIVE_VIEWER_PROFILE,nativeViewerCapabilities} from '../shared/native-viewer-adapter.mjs';
import {nativeResourceCheck,NATIVE_RESOURCE_DEFAULTS,traceNativeTriangle} from '../shared/native-resource-budget.mjs';
import {verifyNativeBundle} from '../shared/native-bundle-verifier.mjs';
import {nativeArchiveIdentity,matchNativeCheckReport,MAX_NATIVE_CHECK_REPORT_BYTES} from '../shared/native-check-report.mjs';
import {MAX_ADAPTER_ZIP_BYTES} from '../shared/stored-zip.mjs';
import {MAX_SIMULATION_HANDOFF_BYTES} from '../shared/simulation-handoff.mjs';
const NativeGeometryPreview=defineAsyncComponent(()=>import('./NativeGeometryPreview.vue'));
const previewScene=shallowRef(null),previewOpen=ref(false);
let disposed=false;onBeforeUnmount(()=>{disposed=true;});
const purpose=ref('geometry'),required=computed(()=>purpose.value==='physics'?['physicalMaterialExecution','rigidBodySimulation']:['sceneGeometry']),capabilities=computed(()=>nativeViewerCapabilities(required.value));
const maxTriangles=ref(NATIVE_RESOURCE_DEFAULTS.maxTriangles),cpuMiB=ref(64),lastManifest=shallowRef(null),triangle=ref(0);
const budget=()=>{if(!Number.isInteger(cpuMiB.value)||cpuMiB.value<1||cpuMiB.value>4096)throw Error('Native CPU mesh budget must be 1–4096 whole MiB');return {maxTriangles:maxTriangles.value,maxLogicalCpuMeshBytes:cpuMiB.value*1048576};};
const trace=computed(()=>{if(!lastManifest.value)return null;try{return {value:traceNativeTriangle(lastManifest.value,triangle.value)};}catch(error){return {error:error.message};}});
const busy=ref(false),message=ref(''),archiveIdentity=shallowRef(null),checkReport=shallowRef(null),reportMessage=ref('');function clearBundle(){previewOpen.value=false;previewScene.value=null;lastManifest.value=null;archiveIdentity.value=null;checkReport.value=null;reportMessage.value='';}watch([purpose,maxTriangles,cpuMiB],()=>{message.value='';clearBundle();});
async function fileSelected(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;busy.value=true;clearBundle();try{nativeResourceCheck(1,budget());if(file.size>MAX_SIMULATION_HANDOFF_BYTES)throw Error('Simulation handoff exceeds 8 MiB');const {bytes,manifest,receiverScene}=await nativeViewerZip(await file.text(),{requiredFeatures:required.value,resourceBudget:budget()});const identity=await nativeArchiveIdentity(bytes);if(disposed)return;archiveIdentity.value=identity;previewScene.value=receiverScene;const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'})),link=document.createElement('a');link.href=url;link.download='terratec-native-viewer.zip';link.click();lastManifest.value=manifest;triangle.value=0;setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='Native viewer bundle exported: '+manifest.summary.triangles+' triangles. Geometry supported; physical-material execution unsupported.';}catch(error){message.value=error.message;}finally{busy.value=false;}}
async function bundleSelected(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;busy.value=true;clearBundle();message.value='';try{const limits=budget();if(file.size>MAX_ADAPTER_ZIP_BYTES)throw Error('Native bundle exceeds archive size limit');const bytes=new Uint8Array(await file.arrayBuffer()),result=await verifyNativeBundle(bytes,limits),identity=await nativeArchiveIdentity(bytes);if(disposed)return;archiveIdentity.value=identity;previewScene.value=result.receiverScene;lastManifest.value=result.manifest;triangle.value=0;message.value='Verified native bundle: archive CRCs, source geometry, resource claims and element mappings match. '+result.manifest.summary.triangles+' triangles. Source consistency only; author identity and rendering are not verified.';}catch(error){if(!disposed)message.value=error.message;}finally{busy.value=false;}}
async function reportSelected(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value||!lastManifest.value||!archiveIdentity.value)return;busy.value=true;checkReport.value=null;reportMessage.value='';try{if(file.size>MAX_NATIVE_CHECK_REPORT_BYTES)throw Error('Native check report exceeds 64 KiB');const result=matchNativeCheckReport(await file.text(),{manifest:lastManifest.value,...archiveIdentity.value});if(disposed)return;checkReport.value=result;reportMessage.value='Matching imported '+result.kind+' report for this exact ZIP. This is recorded evidence, not a new native run or authenticated proof.';}catch(error){if(!disposed)reportMessage.value=error.message;}finally{busy.value=false;}}
</script>
<template><section aria-label="Native viewer adapter"><h4>TerraFlux native viewer adapter</h4><p class="hint">Target: {{ NATIVE_VIEWER_PROFILE.id }} at {{ NATIVE_VIEWER_PROFILE.commit.slice(0,7) }}. Choose a checksummed simulation handoff to download scene.json, OBJ geometry and provenance sidecars in one ZIP. This is native-viewer geometry ingestion; physical materials and live simulation are not executed.</p><label>Native adapter purpose<select v-model="purpose" :disabled="busy" aria-label="Native adapter purpose"><option value="geometry">Geometry viewer</option><option value="physics">Physical simulation</option></select></label><p data-testid="native-capability-status" role="status">{{ capabilities.status }}{{ capabilities.unsupported.length?': '+capabilities.unsupported.join(', '):'' }}</p><p class="hint">Capabilities describe the pinned source profile. Native rendering still needs a runtime smoke check on the receiving graphics setup.</p><label>Native triangle limit<input v-model.number="maxTriangles" :disabled="busy" type="number" min="1" max="2000000" step="1"></label><label>Native logical CPU mesh budget MiB<input v-model.number="cpuMiB" :disabled="busy" type="number" min="1" max="4096" step="1"></label><p class="hint">Export policy only: logical retained mesh bytes exclude parser peak memory, textures, GPU resources and framebuffers. The reviewed native vertex layout is checked by the pinned C++ harness.</p><label>Export native viewer bundle from handoff<input :disabled="busy||capabilities.status!=='supported-by-profile'" type="file" accept=".json,application/json" @change="fileSelected"></label><label>Verify native viewer bundle<input :disabled="busy" type="file" accept=".zip,application/zip" @change="bundleSelected"></label><p class="hint">Read-only verification accepts the exact TerraTec export format and applies the current resource limits. It does not load a project or execute simulation.</p><p data-testid="native-adapter-message" role="status">{{ message }}</p><div v-if="lastManifest"><button :disabled="busy||!previewScene" @click="previewOpen=true">Preview native source geometry</button><NativeGeometryPreview v-if="previewOpen&&previewScene" :scene-data="previewScene" :manifest="lastManifest" :archive-identity="archiveIdentity" :triangle="triangle" @select="triangle=$event" @close="previewOpen=false"/><p data-testid="native-archive-identity">ZIP SHA-256: {{ archiveIdentity?.archiveSha256 }}</p><label>Import native check report<input :disabled="busy" type="file" accept=".json,application/json" @change="reportSelected"></label><p data-testid="native-check-report-message" role="status">{{ reportMessage }}</p><p v-if="checkReport" data-testid="native-check-report-summary">{{ checkReport.kind }} · {{ checkReport.triangles }} triangles<span v-if="checkReport.kind==='render'"> · {{ checkReport.visibleObjPixels }} visible pixels in direct and offscreen modes · {{ checkReport.backend }}</span><span v-else> · {{ checkReport.logicalCpuMeshBytes }} logical CPU mesh bytes</span></p><p class="hint">Imported reports are checked for consistency with this ZIP. They do not verify the author, rerun native checks on this device, or enable live physics.</p><p data-testid="native-budget-report">{{ lastManifest.resources.usage.logicalCpuMeshBytes }} logical CPU mesh bytes · {{ lastManifest.resources.utilization.logicalCpuMeshPercent }}% of budget · {{ lastManifest.summary.triangles }} triangles</p><label>Native zero-based triangle<input v-model.number="triangle" type="number" min="0" :max="lastManifest.summary.triangles-1" step="1"></label><p data-testid="native-source-trace">{{ trace?.error??JSON.stringify(trace?.value) }}</p><p class="hint">Range lookup uses the exported or verified bundle model. This does not add picking support to the engine's single mesh node.</p></div></section></template>
